#!/usr/bin/env bash
# SPDX-License-Identifier: Apache-2.0
#
# gen_vmlinux.sh - produce include/vmlinux.h for BPF CO-RE builds.
#
# Preference order:
#   1. bpftool btf dump file /sys/kernel/btf/vmlinux format c   (real types)
#   2. bpftool btf dump file <first BTF file found>             (fallback paths)
#   3. a minimal, explicitly-labelled stub with just the types used by
#      src/bpf/xsypher.bpf.c, so that syntax/compile checks still succeed in
#      restricted build sandboxes that have no kernel BTF at all.
#
# The generated file is a build artifact: it is git-ignored and must be
# regenerated on the target kernel for a production load.
set -Eeuo pipefail

SCRIPT_DIR="$(cd -- "$(dirname -- "${BASH_SOURCE[0]}")" && pwd)"
REPO_ROOT="$(cd -- "${SCRIPT_DIR}/.." && pwd)"
OUT="${1:-${REPO_ROOT}/include/vmlinux.h}"
FORCE="${FORCE:-0}"

log()  { printf '[gen_vmlinux] %s\n' "$*" >&2; }
die()  { printf '[gen_vmlinux] ERROR: %s\n' "$*" >&2; exit 1; }

if [[ -s "${OUT}" && "${FORCE}" != "1" ]]; then
    log "using existing ${OUT} (set FORCE=1 to regenerate)"
    exit 0
fi

mkdir -p "$(dirname -- "${OUT}")"

BtfCandidates=(
    /sys/kernel/btf/vmlinux
    /boot/vmlinux-$(uname -r)
    /usr/lib/debug/boot/vmlinux-$(uname -r)
    /usr/lib/debug/lib/modules/$(uname -r)/vmlinux
)

have_bpftool=0
if command -v bpftool >/dev/null 2>&1; then
    have_bpftool=1
else
    log "bpftool not found in PATH"
fi

if [[ "${have_bpftool}" -eq 1 ]]; then
    for candidate in "${BtfCandidates[@]}"; do
        [[ -r "${candidate}" ]] || continue
        log "dumping BTF from ${candidate}"
        tmp="${OUT}.tmp.$$"
        if bpftool btf dump file "${candidate}" format c >"${tmp}" 2>/dev/null \
            && [[ -s "${tmp}" ]]; then
            mv "${tmp}" "${OUT}"
            log "wrote $(wc -l <"${OUT}") lines to ${OUT}"
            exit 0
        fi
        rm -f "${tmp}"
        log "failed to dump ${candidate}, trying next candidate"
    done
    log "no usable kernel BTF found"
else
    log "skipping BTF dump (bpftool unavailable)"
fi

# --------------------------------------------------------------------------
# Minimal fallback: only the types the BPF program actually references.
# This is NOT the real kernel ABI - it exists so that CI and air-gapped build
# sandboxes can still type-check the CO-RE program.  Always regenerate from
# /sys/kernel/btf/vmlinux before loading the object on a real host.
# --------------------------------------------------------------------------
log "writing minimal fallback vmlinux.h (compile checks only)"
cat >"${OUT}" <<'FALLBACK_HEADER'
/* Minimal vmlinux.h fallback generated by scripts/gen_vmlinux.sh.
 *
 * WARNING: this is NOT the kernel's BTF.  It exists only so that
 * `clang -target bpf` can type-check src/bpf/xsypher.bpf.c in sandboxes that
 * have no /sys/kernel/btf/vmlinux and no bpftool.  Regenerate this file on the
 * target kernel before loading the object for real:
 *
 *     bpftool btf dump file /sys/kernel/btf/vmlinux format c > include/vmlinux.h
 */
#ifndef __VMLINUX_H__
#define __VMLINUX_H__

#ifndef BPF_NO_PRESERVE_ACCESS_INDEX
#pragma clang attribute push (__attribute__((preserve_access_index)), apply_to = record)
#endif

typedef signed char __s8;
typedef unsigned char __u8;
typedef short int __s16;
typedef short unsigned int __u16;
typedef int __s32;
typedef unsigned int __u32;
typedef long long int __s64;
typedef long long unsigned int __u64;
typedef __u8 u8;
typedef __u16 u16;
typedef __u32 u32;
typedef __u64 u64;
typedef __s32 s32;
typedef __s64 s64;
typedef _Bool bool;
typedef __u16 __be16;
typedef __u32 __be32;
typedef __u32 __wsum;
typedef __u32 uid_t;
typedef __u32 gid_t;
typedef int pid_t;
typedef unsigned int umode_t;
typedef __u32 dev_t;

/* Map and helper enums normally carried in the kernel's own BTF. */
enum bpf_map_type {
    BPF_MAP_TYPE_UNSPEC = 0,
    BPF_MAP_TYPE_HASH = 1,
    BPF_MAP_TYPE_ARRAY = 2,
    BPF_MAP_TYPE_PROG_ARRAY = 3,
    BPF_MAP_TYPE_PERF_EVENT_ARRAY = 4,
    BPF_MAP_TYPE_PERCPU_HASH = 5,
    BPF_MAP_TYPE_PERCPU_ARRAY = 6,
    BPF_MAP_TYPE_STACK_TRACE = 7,
    BPF_MAP_TYPE_LRU_HASH = 9,
    BPF_MAP_TYPE_LRU_PERCPU_HASH = 10,
    BPF_MAP_TYPE_QUEUE = 22,
    BPF_MAP_TYPE_STACK = 23,
    BPF_MAP_TYPE_RINGBUF = 27,
};

struct list_head {
    struct list_head *next;
    struct list_head *prev;
};

struct callback_head {
    struct callback_head *next;
    void (*func)(struct callback_head *head);
};

struct ns_common {
    unsigned int inum;
};

typedef struct {
    int counter;
} atomic_t;

typedef struct {
    long long counter;
} atomic64_t;

struct kref {
    atomic_t refcount;
};

struct upid {
    int nr;
    void *ns;
};

struct pid {
    struct kref count;
    struct upid numbers[1];
};

struct uid_gid_extent;
struct uid_gid_map {
    __u32 nr_extents;
    union {
        struct uid_gid_extent *forward;
        struct uid_gid_extent *reverse;
    };
};

struct user_namespace {
    struct uid_gid_map uid_map;
    struct uid_gid_map gid_map;
    struct ns_common ns;
};

struct uts_namespace {
    struct ns_common ns;
};

struct ipc_namespace {
    struct ns_common ns;
};

struct mnt_namespace {
    struct ns_common ns;
};

struct pid_namespace {
    struct ns_common ns;
};

struct net {
    struct ns_common ns;
};

struct cgroup {
    struct ns_common ns;
};

struct nsproxy {
    atomic_t count;
    struct uts_namespace *uts_ns;
    struct ipc_namespace *ipc_ns;
    struct mnt_namespace *mnt_ns;
    struct pid_namespace *pid_ns_for_children;
    struct net *net_ns;
    struct user_namespace *time_ns_for_children;
    struct cgroup_namespace *cgroup_ns;
};

struct cgroup_namespace {
    struct ns_common ns;
};

struct cred {
    atomic_t usage;
    uid_t uid;
    gid_t gid;
    uid_t suid;
    gid_t sgid;
    uid_t euid;
    gid_t egid;
    uid_t fsuid;
    gid_t fsgid;
};

enum pid_type {
    PIDTYPE_PID = 0,
    PIDTYPE_TGID = 1,
    PIDTYPE_PGID = 2,
    PIDTYPE_SID = 3,
};

struct task_struct {
    int pid;
    int tgid;
    char comm[16];
    struct task_struct *real_parent;
    struct task_struct *parent;
    struct nsproxy *nsproxy;
    struct cred *cred;
    struct fs_struct *fs;
    struct files_struct *files;
    struct signal_struct *signal;
    void *stack;
    unsigned int flags;
    int prio;
    unsigned int policy;
};

struct fs_struct {
    int umask;
    int in_exec;
    void *root;
    void *pwd;
};

struct files_struct;

struct signal_struct {
    atomic_t live;
    int nr_threads;
};

struct qstr {
    union {
        struct {
            __u32 hash;
            __u32 len;
        };
        __u64 hash_len;
    };
    const unsigned char *name;
};

struct dentry {
    unsigned int d_flags;
    struct qstr d_name;
    struct inode *d_inode;
};

struct vfsmount {
    struct dentry *mnt_root;
    void *mnt_sb;
    int mnt_flags;
};

struct path {
    struct vfsmount *mnt;
    struct dentry *dentry;
};

struct file {
    struct path f_path;
    struct inode *f_inode;
    unsigned int f_flags;
    unsigned int f_mode;
    const struct file_operations *f_op;
};

struct file_operations;

struct super_block {
    dev_t s_dev;
};

struct inode {
    umode_t i_mode;
    __u64 i_ino;
    struct super_block *i_sb;
};

struct kernel_siginfo {
    int si_signo;
    int si_errno;
    int si_code;
    int _pad;
};

struct linux_binprm {
    char buf[256];
    struct file *file;
    const char *filename;
    const char *interp;
    unsigned int interp_flags;
    int argc;
    int envc;
    struct cred *cred;
};

struct socket {
    int state;
    unsigned long type;
    unsigned long flags;
    struct sock *sk;
    const struct proto_ops *ops;
    struct file *file;
};

struct proto_ops;

struct hlist_node {
    struct hlist_node *next;
    struct hlist_node **pprev;
};

typedef __u64 __addrpair;
typedef __u32 __portpair;

struct sock_common {
    union {
        __addrpair skc_addrpair;
        struct {
            __be32 skc_daddr;
            __be32 skc_rcv_saddr;
        };
    };
    union {
        unsigned int skc_hash;
        __u16 skc_u16hashes[2];
    };
    union {
        __portpair skc_portpair;
        struct {
            __be16 skc_dport;
            __u16 skc_num;
        };
    };
    unsigned short skc_family;
    volatile unsigned char skc_state;
    unsigned char skc_reuse;
    unsigned char skc_reuseport;
    int skc_bound_dev_if;
    struct hlist_node skc_bind_node;
    void *skc_prot;
    struct net *skc_net;
};

struct sock {
    struct sock_common __sk_common;
    unsigned int sk_shutdown;
};

struct sockaddr {
    unsigned short sa_family;
    char sa_data[14];
};

struct in_addr {
    __be32 s_addr;
};

struct in6_addr {
    union {
        __u8 u6_addr8[16];
        __be16 u6_addr16[8];
        __be32 u6_addr32[4];
    } in6_u;
    __u8 s6_addr[16];
};

struct sockaddr_in {
    unsigned short sin_family;
    __be16 sin_port;
    struct in_addr sin_addr;
    unsigned char sin_zero[8];
};

struct sockaddr_in6 {
    unsigned short sin6_family;
    __be16 sin6_port;
    __be32 sin6_flowinfo;
    struct in6_addr sin6_addr;
    __u32 sin6_scope_id;
};

/* Opaque stand-in for the kernel's union bpf_attr (real value provided by
 * vmlinux.h BTF on the target). */
union bpf_attr {
    char _[128];
};

#ifndef BPF_NO_PRESERVE_ACCESS_INDEX
#pragma clang attribute pop
#endif

#endif /* __VMLINUX_H__ */
FALLBACK_HEADER

log "wrote fallback header to ${OUT} ($(wc -l <"${OUT}") lines)"
log "set FORCE=1 to overwrite it on a host with real kernel BTF"
